<?php
if(PHP_SAPI!=='cli')exit;
require dirname(__DIR__).'/includes/bootstrap.php';require ROOT_PATH.'/includes/driver_license.php';require __DIR__.'/support/document_pdf.php';
$n=0;function check_license($condition,$label){global $n;if(!$condition)throw new RuntimeException($label);$n++;}
$base=['license_type'=>'Professional','authorized_dl_codes'=>json_encode(['C']),'license_expiration'=>date('Y-m-d',strtotime('+1 year')),'license_verification_status'=>'Verified','license_document_filename'=>'actual-license.pdf','license_verified_by'=>1,'license_verified_at'=>date(DATE_ATOM)];
$truck=['type'=>'Heavy Truck','service_category'=>'Cargo','model'=>'Rigid Cargo'];$trailer=$truck+['requires_trailer_license'=>true];
check_license(driver_license_eligibility($truck,$base)==='','Verified C qualifies rigid cargo');check_license(driver_license_eligibility($trailer,$base)!=='','C cannot qualify trailer');$ce=$base;$ce['authorized_dl_codes']='["C","CE"]';check_license(driver_license_eligibility($trailer,$ce)==='','Explicit verified C and CE qualify trailer');
foreach(['license_verification_status'=>'Unverified','license_type'=>'Non-Professional','license_expiration'=>'2000-01-01','license_document_filename'=>'','license_verified_by'=>null,'license_verified_at'=>null,'authorized_dl_codes'=>'["B2"]'] as $field=>$value){$d=$base;$d[$field]=$value;check_license(driver_license_eligibility($truck,$d)!=='','Reject '.$field);}
check_license(driver_license_eligibility($truck,['license_class'=>'Professional (Class 2, 3)'])!=='','Legacy class never grants C');
check_license(driver_license_eligibility($truck,$base,date('Y-m-d',strtotime('+2 years')))!=='','License must cover scheduled departure');
check_license(vehicle_required_dl_code($truck+['gross_vehicle_weight_kg'=>3500])==='B2','3500kg cargo B2 boundary');check_license(vehicle_required_dl_code($truck+['gross_vehicle_weight_kg'=>3501])==='C','3501kg cargo C boundary');check_license(vehicle_required_dl_code(['type'=>'Heavy Truck','model'=>'Tractor Head'])==='CE','Tractor requires CE');
$path=ROOT_PATH.'/tmp/driver-license-parser-test.pdf';file_put_contents($path,toursphere_test_document_pdf(['DRIVER LICENSE','DL Codes: B2, C, CE','License Type: Professional','License No: N01-23-123456','Expiration Date: 2028-10-12']));$e=driver_license_extract($path,'application/pdf');check_license($e['authorized_dl_codes']===['B2','C','CE'],'Actual searchable PDF code extraction');check_license($e['license_type']==='Professional','Professional extraction');check_license($e['license_no']==='N01-23-123456','Number extraction');check_license($e['license_expiration']==='2028-10-12','Expiry extraction');
file_put_contents($path,toursphere_test_document_pdf(['Non-Professional','DL Codes: CE','Restriction Codes: 2,3']));$e=driver_license_extract($path,'application/pdf');check_license($e['authorized_dl_codes']===['CE'],'CE does not imply C');check_license($e['license_type']==='Non-Professional','Non-Professional never becomes Professional');
file_put_contents($path,toursphere_test_document_pdf(['Professional (Class 2, 3)','Address: C Avenue']));$e=driver_license_extract($path,'application/pdf');check_license($e['authorized_dl_codes']===[],'No inference from restrictions or address');check_license(driver_license_extract($path,'image/png')['supported']===false,'Images require manual review');unlink($path);
$p=db();$p->beginTransaction();try{$id=$p->query('SELECT id FROM drivers ORDER BY id LIMIT 1')->fetchColumn();$p->prepare("UPDATE drivers SET status='Active' WHERE id=?")->execute([$id]);$q=$p->prepare('SELECT status,authorized_dl_codes FROM drivers WHERE id=?');$q->execute([$id]);$d=$q->fetch();check_license($d['status']==='Active'&&$d['authorized_dl_codes']==='[]','Active availability does not invent license codes');}finally{$p->rollBack();}
$p->beginTransaction();try {
 $id=$p->query('SELECT id FROM drivers ORDER BY id LIMIT 1')->fetchColumn();$actor=$p->query('SELECT id FROM users ORDER BY id LIMIT 1')->fetchColumn();
 $q=$p->prepare("UPDATE drivers SET license_type='Professional',authorized_dl_codes=?::jsonb,license_verification_status='Verified',license_document_filename='transaction-test.pdf',license_verification_notes='Rollback-only evidence storage test',license_verified_by=?,license_verified_at=CURRENT_TIMESTAMP,status='Active' WHERE id=? RETURNING *");
 $q->execute(['["C","CE"]',$actor,$id]);$saved=$q->fetch();check_license(driver_license_active($saved),'Database saves explicit verified qualifications with evidence');check_license(driver_license_eligibility($trailer,$saved)==='','Saved CE authorizes combination during rollback test');
 $p->exec('SAVEPOINT invalid_evidence');$failed=false;try{$p->prepare('UPDATE drivers SET license_verification_notes=NULL WHERE id=?')->execute([$id]);}catch(PDOException $e){$failed=true;$p->exec('ROLLBACK TO SAVEPOINT invalid_evidence');}check_license($failed,'Verified record requires verification notes');
 $p->prepare("UPDATE drivers SET authorized_dl_codes='[\"B2\"]'::jsonb,status='Active' WHERE id=?")->execute([$id]);$q=$p->prepare('SELECT status FROM drivers WHERE id=?');$q->execute([$id]);check_license($q->fetchColumn()==='Active','Removing C does not alter availability status');
}finally{$p->rollBack();}
check_license((int)$p->query("SELECT count(*) FROM drivers WHERE status IN ('Assigned','On Trip') AND license_verification_status<>'Verified'")->fetchColumn()===0,'No unverified assigned or on-trip drivers remain');echo "$n driver-license checks passed; database test rolled back.\n";
